-- G24 adaptive foundation and G28 question-specific evidence guidance.
-- Additive, draft-only, Staging application. Existing assessments remain legacy_fixed.
-- Generated by scripts/generate-adaptive-foundation-content.mjs.

begin;

create table if not exists public.adaptive_graph_versions (
  id uuid primary key default gen_random_uuid(),
  graph_version text not null unique,
  methodology_version_id uuid not null references public.methodology_versions(id),
  methodology_version text not null,
  status text not null default 'draft' check (status in ('draft','published','retired')),
  compiled_graph_json jsonb not null,
  graph_fingerprint text not null check (graph_fingerprint ~ '^[0-9a-f]{64}$'),
  question_count integer not null check (question_count >= 0),
  gateway_count integer not null check (gateway_count >= 0),
  oversight_variant_count integer not null check (oversight_variant_count >= 0),
  provenance text not null,
  created_at timestamptz not null default now(),
  published_at timestamptz,
  created_by uuid,
  supersedes_graph_version text references public.adaptive_graph_versions(graph_version),
  check ((status = 'published') = (published_at is not null))
);

create table if not exists public.assessment_navigation_states (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null unique references public.assessments(id) on delete cascade,
  graph_version_id uuid references public.adaptive_graph_versions(id),
  current_question_id text,
  visited_question_ids text[] not null default '{}',
  current_screen text not null default 'question' check (current_screen in ('gateway','question','review','complete')),
  save_sequence bigint not null default 0 check (save_sequence >= 0),
  last_saved_at timestamptz,
  submitted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.assessment_answer_history (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  question_id text not null,
  graph_version_id uuid references public.adaptive_graph_versions(id),
  event_type text not null check (event_type in ('replacement','invalidation','upstream_change')),
  previous_answer jsonb,
  upstream_cause_question_id text,
  reason_code text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.assessment_applicability_profiles (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  question_id text not null,
  graph_version_id uuid not null references public.adaptive_graph_versions(id),
  applicability_state text not null check (applicability_state in ('activity_exists_internal','activity_outsourced','activity_shared_service','activity_absent','unknown')),
  finding_class text,
  recommendation_class text,
  scoring_weight numeric,
  included_in_denominator boolean not null default true,
  excluded_from_denominator_rule text,
  skip_reason text,
  control_visibility_state text not null default 'visible' check (control_visibility_state in ('visible','skipped','redirected','invalidated')),
  redirected_question_id text,
  replacement_question_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (assessment_id, graph_version_id, question_id)
);

create table if not exists public.assessment_integrity_signals (
  id uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  graph_version_id uuid not null references public.adaptive_graph_versions(id),
  signal_id text not null,
  detail jsonb not null default '{}',
  blocking boolean not null default false,
  created_at timestamptz not null default now(),
  unique (assessment_id, graph_version_id, signal_id)
);

create table if not exists public.assessment_evidence_guidance (
  id uuid primary key default gen_random_uuid(),
  question_id uuid not null references public.questions(id),
  question_code text not null,
  methodology_version_id uuid not null references public.methodology_versions(id),
  graph_version_id uuid not null references public.adaptive_graph_versions(id),
  guidance_version text not null,
  status text not null default 'draft' check (status in ('draft','published','retired')),
  good_evidence_looks_like text not null,
  example_artifacts jsonb not null check (jsonb_typeof(example_artifacts) = 'array'),
  likely_evidence_owner text not null,
  content_fingerprint text not null check (content_fingerprint ~ '^[0-9a-f]{64}$'),
  provenance text not null,
  created_at timestamptz not null default now(),
  published_at timestamptz,
  unique (question_id, methodology_version_id, guidance_version),
  check ((status = 'published') = (published_at is not null))
);

alter table public.assessments add column if not exists assessment_mode text not null default 'legacy_fixed';
alter table public.assessments add constraint assessments_assessment_mode_check check (assessment_mode in ('legacy_fixed','adaptive'));
alter table public.assessments add column if not exists graph_version_id uuid references public.adaptive_graph_versions(id);
alter table public.assessments add column if not exists graph_version_snapshot text;
alter table public.assessments add column if not exists graph_fingerprint_snapshot text check (graph_fingerprint_snapshot is null or graph_fingerprint_snapshot ~ '^[0-9a-f]{64}$');
alter table public.assessments add constraint assessments_adaptive_graph_pin_check check ((assessment_mode = 'adaptive') = (graph_version_id is not null));

create index if not exists adaptive_graph_versions_methodology_idx on public.adaptive_graph_versions(methodology_version_id, status);
create index if not exists assessment_navigation_states_graph_idx on public.assessment_navigation_states(graph_version_id);
create index if not exists assessment_answer_history_assessment_idx on public.assessment_answer_history(assessment_id, created_at);
create index if not exists assessment_applicability_profiles_assessment_idx on public.assessment_applicability_profiles(assessment_id, graph_version_id);
create index if not exists assessment_integrity_signals_assessment_idx on public.assessment_integrity_signals(assessment_id, graph_version_id);
create index if not exists assessment_evidence_guidance_question_idx on public.assessment_evidence_guidance(question_code, methodology_version_id);

comment on table public.adaptive_graph_versions is 'Versioned adaptive graph definitions. Draft-only in G24; customer routing is disabled.';
comment on table public.assessment_evidence_guidance is 'Question-specific G28 evidence guidance bound to a graph and methodology version.';
comment on column public.assessments.assessment_mode is 'Legacy assessments remain legacy_fixed; adaptive is reserved for a future approved activation.';

create or replace function public.guard_adaptive_content_immutability() returns trigger language plpgsql set search_path = '' as $$ begin
  if tg_op = 'DELETE' and old.status = 'published' then raise exception 'adaptive_content_published_immutable:%', tg_table_name; end if;
  if tg_op = 'UPDATE' and old.status = 'published' and tg_table_name = 'adaptive_graph_versions' and (to_jsonb(new)->>'graph_version' is distinct from to_jsonb(old)->>'graph_version' or to_jsonb(new)->>'compiled_graph_json' is distinct from to_jsonb(old)->>'compiled_graph_json' or to_jsonb(new)->>'graph_fingerprint' is distinct from to_jsonb(old)->>'graph_fingerprint') then raise exception 'adaptive_graph_published_content_immutable'; end if;
  if tg_op = 'UPDATE' and old.status = 'published' and tg_table_name = 'assessment_evidence_guidance' and (to_jsonb(new)->>'good_evidence_looks_like' is distinct from to_jsonb(old)->>'good_evidence_looks_like' or to_jsonb(new)->>'example_artifacts' is distinct from to_jsonb(old)->>'example_artifacts' or to_jsonb(new)->>'likely_evidence_owner' is distinct from to_jsonb(old)->>'likely_evidence_owner' or to_jsonb(new)->>'content_fingerprint' is distinct from to_jsonb(old)->>'content_fingerprint') then raise exception 'adaptive_guidance_published_content_immutable'; end if;
  return case when tg_op = 'DELETE' then old else new end; end; $$;
drop trigger if exists trg_adaptive_graph_content_immutability on public.adaptive_graph_versions;
create trigger trg_adaptive_graph_content_immutability before insert or update or delete on public.adaptive_graph_versions for each row execute function public.guard_adaptive_content_immutability();
drop trigger if exists trg_adaptive_guidance_content_immutability on public.assessment_evidence_guidance;
create trigger trg_adaptive_guidance_content_immutability before insert or update or delete on public.assessment_evidence_guidance for each row execute function public.guard_adaptive_content_immutability();
create or replace function public.publish_adaptive_graph_version(p_graph_version text) returns public.adaptive_graph_versions language plpgsql security definer set search_path = '' as $$ declare v_graph public.adaptive_graph_versions; begin select * into v_graph from public.adaptive_graph_versions where graph_version = p_graph_version for update; if not found then raise exception 'adaptive_graph_not_found:%', p_graph_version; end if; if v_graph.status <> 'draft' then raise exception 'adaptive_graph_not_draft:%', p_graph_version; end if; update public.adaptive_graph_versions set status = 'published', published_at = now() where id = v_graph.id returning * into v_graph; return v_graph; end; $$;
revoke all on function public.publish_adaptive_graph_version(text) from public, anon, authenticated; grant execute on function public.publish_adaptive_graph_version(text) to service_role;

alter table public.adaptive_graph_versions enable row level security;
alter table public.assessment_navigation_states enable row level security;
alter table public.assessment_answer_history enable row level security;
alter table public.assessment_applicability_profiles enable row level security;
alter table public.assessment_integrity_signals enable row level security;
alter table public.assessment_evidence_guidance enable row level security;
revoke all on public.adaptive_graph_versions, public.assessment_navigation_states, public.assessment_answer_history, public.assessment_applicability_profiles, public.assessment_integrity_signals, public.assessment_evidence_guidance from public, anon, authenticated;
grant select, insert, update on public.adaptive_graph_versions to service_role;
grant select, insert, update on public.assessment_navigation_states to service_role;
grant select, insert on public.assessment_answer_history to service_role;
grant select, insert, update on public.assessment_applicability_profiles to service_role;
grant select, insert, update on public.assessment_integrity_signals to service_role;
grant select, insert, update on public.assessment_evidence_guidance to service_role;
revoke all on function public.publish_adaptive_graph_version(text) from public, anon, authenticated;
grant execute on function public.publish_adaptive_graph_version(text) to service_role;

