ur organisation sell online or accept digital or card payments?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":7,"responseOptions":[{"value":"yes","label":"yes"},{"value":"platform","label":"platform"},{"value":"no","label":"no"},{"value":"unknown","label":"unknown"}],"scoringStatus":"profile_only"},{"questionId":"G09","section":"Digital and customers","prompt":"Does your organisation hold personal information about customers, clients or employees?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":8,"responseOptions":[{"value":"yes","label":"yes"},{"value":"no","label":"no"},{"value":"unknown","label":"unknown"}],"scoringStatus":"profile_only"},{"questionId":"G10","section":"Operations","prompt":"Does your organisation process refunds, credit notes or manual adjustments?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":9,"responseOptions":[{"value":"yes","label":"yes"},{"value":"no","label":"no"},{"value":"unknown","label":"unknown"}],"scoringStatus":"profile_only"},{"questionId":"G11","section":"Operations","prompt":"Does the organisation operate from more than one site, store or project location?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":10,"responseOptions":[{"value":"yes","label":"yes"},{"value":"no","label":"no"},{"value":"unknown","label":"unknown"}],"scoringStatus":"profile_only"},{"questionId":"G12","section":"People and payroll","prompt":"Does your organisation use temporary, seasonal or subcontracted workers?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":11,"responseOptions":[{"value":"yes","label":"yes"},{"value":"no","label":"no"},{"value":"unknown","label":"unknown"}],"scoringStatus":"profile_only"},{"questionId":"G13","section":"Digital and customers","prompt":"Do employees work remotely or do you depend on third-party digital platforms?","questionType":"single_select","gatewayStatus":"gateway","sortOrder":12,"responseOptions":[{"value":"