isHardGate":false,"sortOrder":2,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D1-Q02"},{"questionId":"D1-Q03","questionCode":"D1-Q03","domainCode":"D1","prompt":"Fraud risks, incidents and control weaknesses are reported to senior leadership or a governance forum on a defined rhythm.","controlObjective":"Give leadership a predictable, evidence-based view of fraud exposure, incidents and control weaknesses.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":3,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D1-Q03"},{"questionId":"D1-Q04","questionCode":"D1-Q04","domainCode":"D1","prompt":"Management owns fraud risk, while internal audit or assurance functions provide independent review where they exist.","controlObjective":"Separate management ownership of fraud risk from independent assurance over that ownership.","weight":1.5,"isCritical":true,"isHardGate":true,"sortOrder":4,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D1-Q04"},{"questionId":"D1-Q05","questionCode":"D1-Q05","domainCode":"D1","prompt":"The organisation has written fraud guidance, policies or procedures explaining how fraud should be prevented, detected, reported and managed.","controlObjective":"Put the organisation’s fraud rules in writing so expected behaviour and required process are not left to individual interpretation.","weight":1,"isCritical":false,"isHardGate":false,"sortOrder":5,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D1-Q05"},{"questionId":"D1-Q06","questionCode":"D1-Q06","domainCode":"D1","prompt":"Leadership receives updates on emerging fraud threats affecting the sector, operating model or customer and supplier environment.","controlObjective":"Keep leadership informed of fraud threats actually emerging in the sector, operating model and counterparty base.","weight":1,"isCritical":false,"isHardGate":false,"sortOrder":6,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D1-Q06"},{"questionId":"D2-Q01","questionCode":"D2-Q01","domainCode":"D2","prompt":"The organisation has completed a structured fraud risk assessment within the past two years.","controlObjective":"Establish a current, structured and documented view of where the organisation is actually exposed to fraud.","weight":1.5,"isCritical":true,"isHardGate":true,"sortOrder":7,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D2-Q01"},{"questionId":"D2-Q02","questionCode":"D2-Q02","domainCode":"D2","prompt":"Fraud risks have been mapped across important processes such as procurement, payments, refunds, claims, stock, supplier management or service delivery.","controlObjective":"Map fraud risk to the specific operational processes where value can actually be diverted.","weight":1.5,"isCritical":true,"isHardGate":true,"sortOrder":8,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D2-Q02"},{"questionId":"D2-Q03","questionCode":"D2-Q03","domainCode":"D2","prompt":"New systems, channels, products, services or operational changes include fraud-risk review before implementation.","controlObjective":"Force a fraud-risk review into the design of new systems, channels, products, services and operational changes before they go live.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":9,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D2-Q03"},{"questionId":"D2-Q04","questionCode":"D2-Q04","domainCode":"D2","prompt":"Fraud risks are refreshed when the organisation changes how it operates, serves customers or works with suppliers.","controlObjective":"Keep the fraud risk picture aligned to how the organisation currently operates rather than how it operated when the assessment was written.