"evidenceReference":"G28-D9-Q05"},{"questionId":"D9-Q06","questionCode":"D9-Q06","domainCode":"D9","prompt":"Employees have safe ways to raise concerns and believe those concerns will be taken seriously.","controlObjective":"Build genuine confidence that raising a concern is safe and will be taken seriously.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":62,"applicabilityCondition":{"any":[{"questionId":"G02","in":["small","medium","large","unknown"]}]},"redirectWhen":null,"skipReasonCode":"gateway_no_employee_base","evidenceReference":"G28-D9-Q06"},{"questionId":"D10-Q01","questionCode":"D10-Q01","domainCode":"D10","prompt":"The organisation periodically reviews its fraud risks and control environment.","controlObjective":"Periodically re-examine the fraud risk profile and the control environment as a whole rather than only at incident time.","weight":1.5,"isCritical":true,"isHardGate":true,"sortOrder":63,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q01"},{"questionId":"D10-Q02","questionCode":"D10-Q02","domainCode":"D10","prompt":"Fraud incidents or control failures are analysed to understand root causes and control weaknesses.","controlObjective":"Analyse incidents and control failures to understand why they were possible, not merely what happened.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":64,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q02"},{"questionId":"D10-Q03","questionCode":"D10-Q03","domainCode":"D10","prompt":"Lessons from investigations or incidents are translated into control, process, training or monitoring improvements.","controlObjective":"Translate lessons from investigations and incidents into actual changes in controls, process, training or monitoring.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":65,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q03"},{"questionId":"D10-Q04","questionCode":"D10-Q04","domainCode":"D10","prompt":"The organisation monitors fraud trends affecting its sector, geography, customer environment or supplier base.","controlObjective":"Monitor fraud trends affecting the organisation’s sector, geography, customer environment and supplier base.","weight":1,"isCritical":false,"isHardGate":false,"sortOrder":66,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q04"},{"questionId":"D10-Q05","questionCode":"D10-Q05","domainCode":"D10","prompt":"Fraud risk is considered when new systems, products, services, processes or operational changes are implemented.","controlObjective":"Ensure fraud risk is considered whenever new systems, products, services, processes or operational changes are implemented.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":67,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q05"},{"questionId":"D10-Q06","questionCode":"D10-Q06","domainCode":"D10","prompt":"Leadership periodically reviews whether key fraud controls remain effective, resourced and fit for purpose.","controlObjective":"Have leadership periodically confirm that key fraud controls remain effective, adequately resourced and fit for purpose.","weight":1.25,"isCritical":false,"isHardGate":false,"sortOrder":68,"applicabilityCondition":null,"redirectWhen":null,"skipReasonCode":null,"evidenceReference":"G28-D10-Q06"}],"oversightVariants":[{"questionId":"OV-D3-Q03","replaces":"D3-Q03","domainCode":"D3","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"Supplier management is outsourced; the organisation retains assurance over provider vetting and due diligence.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."},{"questionId":"OV-D7-Q01","replaces":"D7-Q01","domainCode":"D7","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"The organisation defines and monitors the third-party vetting standard applied on its behalf.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."},{"questionId":"OV-D7-Q02","replaces":"D7-Q02","domainCode":"D7","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"The organisation retains controls over supplier selection, price integrity and conflict disclosure where procurement is outsourced.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."},{"questionId":"OV-D7-Q04","replaces":"D7-Q04","domainCode":"D7","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"The organisation independently verifies supplier banking changes before provider-executed payments are released.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."},{"questionId":"OV-D8-Q02","replaces":"D8-Q02","domainCode":"D8","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"The organisation reviews fraud, dispute and account-security reporting from the third-party platform it uses.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."},{"questionId":"OV-G07","replaces":null,"domainCode":"D7","questionType":"maturity_scale","gatewayStatus":"oversight_variant","prompt":"The organisation independently reviews an externally processed payroll register for unknown, duplicate or altered records.","scoringStatus":"scored_as_third_party_governance","displayGuidance":"Outsourcing moves the activity, not the accountability; assess the retained governance control."}],"applicabilityStates":["activity_exists_internal","activity_outsourced","activity_shared_service","activity_absent","unknown"],"scoringStatuses":["not_applicable","outsourced","unknown","not_implemented","partially_implemented","implemented","invalidated_by_upstream","profile_only","scored_as_third_party_governance"],"skipReasonCodes":{"gateway_no_third_parties":"No external suppliers or contractors were confirmed.","gateway_no_procurement":"No procurement or buying activity was confirmed.","gateway_no_refunds_or_adjustments":"No refunds, credits, write-offs or manual adjustments were confirmed.","gateway_no_high_risk_handling":"No relevant cash, stock, refund, adjustment or temporary-worker exposure was confirmed.","gateway_no_digital_footprint":"No relevant online, digital-payment or platform dependency was confirmed.","gateway_no_digital_or_identity_footprint":"No relevant digital channel or personal-information exposure was confirmed.","gateway_no_employee_base":"No employee base beyond the owner was confirmed.","upstream_answer_changed":"An upstream gateway answer changed the active pathway.","redirected_to_oversight_variant":"The activity is outsourced, so the retained-governance equivalent was used."},"graphInvariants":{"questionCount":68,"gatewayCount":14,"oversightVariantCount":6,"gatewayBlockCount":4,"customerRoutingEnabled":false,"scoringEngineChanged":false},"graphFingerprint":"fa4505253f7e85a76f37e87e0836db76c553a786a4030fe29298153fc3b8f7ab"}'::jsonb, 'fa4505253f7e85a76f37e87e0836db76c553a786a4030fe29298153fc3b8f7ab', 68, 14, 6, 'G24 approved adaptive foundation; draft only; no customer routing.'
from public.methodology_versions mv where mv.version_code = 'MFRS-V1.1'
on conflict (graph_version) do nothing;

insert into public.assessment_evidence_guidance (question_id, question_code, methodology_version_id, graph_version_id, guidance_version, status, good_evidence_looks_like, example_artifacts, likely_evidence_owner, content_fingerprint, provenance)
select q.id, g.questionCode, mv.id, ag.id, g.guidanceVersion, 'draft', g.goodEvidenceLooksLike, g.exampleArtifacts::jsonb, g.likelyEvidenceOwner, g.contentFingerprint, 'G28 question-specific guidance generated from the authoritative playbook registry.'
from jsonb_to_recordset('[{"questionCode":"D1-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A named senior executive owns the fraud-risk programme, its budget, unresolved exceptions and reporting to the governing body. Good evidence identifies the accountable owner and shows names one accountable executive and decision rights; shows decisions, owners and due dates; shows escalation after 30 days overdue.","exampleArtifacts":["Signed executive accountability mandate","Last two fraud-risk governance packs","Overdue-action escalation log"],"likelyEvidenceOwner":"Named fraud-risk executive","controlObjective":"Give one senior executive explicit authority and accountability for fraud-risk decisions.","contentFingerprint":"83bf73892d3b4a205164b261302266a597e3b72a2c994192c985cd3766e3fec1","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D1-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Fraud appears as a discrete registered risk with an owner, inherent and residual ratings, linked controls and a review cycle, inside the same register the governing body already uses. Good evidence identifies the accountable owner and shows fraud is a discrete entry, not folded into general operational risk; shows owner, rating basis and linked controls; rating changes carry written justification.","exampleArtifacts":["Enterprise risk register extract showing the fraud entry","Inherent and residual ratings with written rationale","Approved fraud risk-appetite statement","Minutes recording register review"],"likelyEvidenceOwner":"Head of Risk","controlObjective":"Carry fraud risk as a named risk inside the organisation-wide risk and governance framework rather than as an informal concern.","contentFingerprint":"5ccf64c2c5acec77c1afc68106b08874f9e3394e9eaf6daee15b388c2ffb64d5","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D1-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A named forum receives a standard fraud report on a fixed cadence covering incidents, losses, control failures, overdue actions and trend commentary, with decisions minuted. Good evidence identifies the accountable owner and shows consistent template across consecutive periods; quantifies incidents, losses and overdue actions rather than narrative only; minutes show decisions, owners and dates.","exampleArtifacts":["Last two fraud reports on the standard template","Forum terms of reference naming the standing agenda item","Minutes recording decisions and owners","Overdue-action ageing schedule"],"likelyEvidenceOwner":"Named fraud-risk executive","controlObjective":"Give leadership a predictable, evidence-based view of fraud exposure, incidents and control weaknesses.","contentFingerprint":"304886291d202560353be9051caf5c83712dec816525ee89a83fd989543aaa5b","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D1-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Management designs and operates fraud controls; internal audit or another independent function periodically tests them and reports without assuming management responsibility. Good evidence identifies the accountable owner and shows separates operation from testing for each key control; gives assurance unrestricted reporting access; records conflicts and recusals.","exampleArtifacts":["Approved fraud-risk RACI","Internal audit charter or assurance mandate","Audit-committee minutes showing independent reporting"],"likelyEvidenceOwner":"Head of Risk and business control owners","controlObjective":"Separate management ownership of fraud risk from independent assurance over that ownership.","contentFingerprint":"8dc36ec091dbe61e6d46db2683b7c535953fbb5982943ab4366ad406b81700a8","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D1-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Approved, version-controlled fraud policy and supporting procedures define prohibited conduct, prevention and detection duties, reporting routes, investigation handling and consequences, and reach the full workforce. Good evidence identifies the accountable owner and shows version-controlled with named owner and review date; states consequences and reporting routes explicitly; reaches the full workforce including non-desk and contract staff.","exampleArtifacts":["Approved fraud policy with version and approval date","Supporting reporting and investigation procedures","Publication or intranet availability evidence","Workforce acknowledgement records"],"likelyEvidenceOwner":"Named fraud-risk executive","controlObjective":"Put the organisation’s fraud rules in writing so expected behaviour and required process are not left to individual interpretation.","contentFingerprint":"07a7396812f8e396adbe2809772f35d197e0797d73a02e504dc72bffcbfebfbe","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D1-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Threat information is gathered from named sources, filtered for relevance to the operating model, and presented to leadership with an explicit implication for existing controls. Good evidence identifies the accountable owner and shows cites dated external sources rather than general commentary; links each threat to a named process, channel or control; records an action or an explicit accept decision.","exampleArtifacts":["Named threat-source list","Threat briefing papers presented to leadership","Relevance assessment mapping threats to existing controls","Resulting action or accept decisions"],"likelyEvidenceOwner":"Named fraud-risk executive","controlObjective":"Keep leadership informed of fraud threats actually emerging in the sector, operating model and counterparty base.","contentFingerprint":"78536550129a38c5032a5cd1df651838f889fc852d385d25cc5470d689fbeecb","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A structured fraud risk assessment completed within the past two years covers the material processes, uses a repeatable method, rates inherent and residual risk, names owners and produces a tracked treatment plan. Good evidence identifies the accountable owner and shows completed within the last 24 months; covers the material process population rather than a sample of convenience; every unacceptable residual risk has a named owner and due date.","exampleArtifacts":["Dated fraud risk assessment report","Documented method and participant list","Scenario-level inherent and residual ratings","Approved treatment plan with owners and due dates"],"likelyEvidenceOwner":"Head of Risk","controlObjective":"Establish a current, structured and documented view of where the organisation is actually exposed to fraud.","contentFingerprint":"8e371fdac436c7d6f8b7a9a4da482273f7f2dd333ad43b8852d244c9534a2aad","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Each material process — procurement, payments, refunds, claims, stock, supplier management and service delivery as applicable — has documented fraud scenarios, the roles able to execute them, and the controls relied upon. Good evidence identifies the accountable owner and shows names specific processes rather than functions; identifies the roles and permissions able to execute each scenario; signed by the accountable process owner.","exampleArtifacts":["Process inventory identifying material value-bearing processes","Per-process fraud scenario map","Control linkage showing preventive and detective controls","Process-owner sign-off"],"likelyEvidenceOwner":"Head of Risk with named process owners","controlObjective":"Map fraud risk to the specific operational processes where value can actually be diverted.","contentFingerprint":"b3a90054495ba7a0c165204f8dfaf8ab1df547ff2ce12605e151682f583ce1a5","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Change governance includes a mandatory fraud-risk assessment step with defined triggers, a competent reviewer and a documented decision closed before implementation. Good evidence identifies the accountable owner and shows trigger criteria are written and objective; review predates implementation; shows decision, reviewer and any accepted residual risk.","exampleArtifacts":["Change process documentation showing the fraud gate and triggers","Completed fraud reviews for recent qualifying changes","Accept or remediate decisions","Evidence the gate blocked or released go-live"],"likelyEvidenceOwner":"Change and project governance owner","controlObjective":"Force a fraud-risk review into the design of new systems, channels, products, services and operational changes before they go live.","contentFingerprint":"15fda13b5fc341451fbe76b04e302dd9db333ec979971623e06119941cbefffe","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Defined business-change triggers require a fraud-risk refresh, with refreshed scenarios and control expectations recorded against the changed operating model. Good evidence identifies the accountable owner and shows triggers are objective and cover outsourcing and channel change; refresh is traceable to a specific dated change; resulting gaps carry owners and due dates.","exampleArtifacts":["Written refresh trigger criteria","Refresh records linked to specific change events","Updated process fraud maps","Treatment-plan entries arising from refreshes"],"likelyEvidenceOwner":"Head of Risk","controlObjective":"Keep the fraud risk picture aligned to how the organisation currently operates rather than how it operated when the assessment was written.","contentFingerprint":"68f7fab1f2c4afdadf99c71ec4e60c8ec12f1786b05835f4ba5044a84f349ea3","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Third-party fraud scenarios are assessed by relationship type and risk tier, covering collusion, substitution, over-billing, impersonation and misuse of delegated authority, with controls mapped per tier. Good evidence identifies the accountable owner and shows covers the complete third-party population including contractors and intermediaries; addresses delegated authority and system access explicitly; links each tier to named controls.","exampleArtifacts":["Third-party inventory with relationship type and risk tier","Tiered fraud scenario assessment","Control mapping per tier","Residual gaps recorded in the treatment plan"],"likelyEvidenceOwner":"Procurement / Vendor Risk","controlObjective":"Assess the fraud risk introduced by suppliers, contractors, agents, intermediaries and other third parties acting for or with the organisation.","contentFingerprint":"2d4b77f2c5c48c29e61024da686c33bf3a0f1ed3d7f6ec0ca8a96a68d71b644f","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Named sources are monitored on a defined rhythm, relevance is assessed against the organisation’s processes and channels, and material threats generate a control review or an explicit accept decision. Good evidence identifies the accountable owner and shows sources are specific and dated rather than generic media scanning; relevance assessed against named internal processes; every material threat has a decision and owner.","exampleArtifacts":["Named source list with assigned responsibility","Threat log with dated entries","Relevance assessment against processes and channels","Control reviews or accept decisions arising"],"likelyEvidenceOwner":"Fraud risk analyst or nominated owner","controlObjective":"Track fraud threats emerging in the organisation’s own industry, geography and operating environment and convert them into control questions.","contentFingerprint":"d5029e47c47165717807c5fb484706a3be991ec625017b0111dd2bbd3c446ea6","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Insider fraud scenarios are assessed explicitly, including approval-limit abuse, permission accumulation, override use and collusion between roles, with compensating controls identified where separation is not achievable. Good evidence identifies the accountable owner and shows names realistic role combinations rather than abstract insider risk; addresses override and emergency access explicitly; states the compensating control and its operator where separation fails.","exampleArtifacts":["Insider scenario analysis","Delegation of authority matrix","Incompatible-duty and permission conflict analysis","Documented compensating controls where separation is not possible"],"likelyEvidenceOwner":"Head of Risk","controlObjective":"Consider deliberately how insiders could misuse authority, privileged access, approvals, system permissions or process gaps.","contentFingerprint":"f87d2ff5780b62c356ab6bdcd56d76ab2c355e93ccf60a797431888313aac4d3","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D2-Q08","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Each digital channel in use — portals, online forms, messaging journeys, loyalty programmes and service platforms — is assessed for enrolment, transaction, data-change and benefit-abuse fraud, with controls mapped per channel. Good evidence identifies the accountable owner and shows covers every channel actually in use, including messaging journeys; distinguishes enrolment, transaction, data-change and benefit-abuse risk; links each risk to a named control.","exampleArtifacts":["Digital channel inventory","Per-channel fraud risk assessment","Control mapping for enrolment, transaction, data change and benefit abuse","Residual gaps in the treatment plan"],"likelyEvidenceOwner":"Digital channel owner","controlObjective":"Assess fraud risk arising through customer and user digital channels where the organisation operates them.","contentFingerprint":"ef81911d23d024550b8d9f9d8e717947e9bff5e328bb9cd08a4dfdaddddb73a9","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"High-risk processes have documented separation between initiation, approval, processing and reconciliation, enforced in system roles, with named compensating controls wherever headcount prevents full separation. Good evidence identifies the accountable owner and shows maps all four duties for each in-scope process; tested against actual user entitlements, not intended design; compensating controls name the independent reviewer.","exampleArtifacts":["Duty-separation matrix per high-risk process","System role configuration showing incompatible-duty blocks","Periodic permission conflict report","Approved compensating controls where separation is not achievable"],"likelyEvidenceOwner":"Named process owners","controlObjective":"Ensure no single person can initiate, approve, process and reconcile the same high-risk transaction.","contentFingerprint":"d20db47f0f0c85e807517353d93e174e5a4731a1c2f9b06fd60f9730b92f9cc9","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Written thresholds define which transactions require secondary approval, the approver is independent of the initiator, and the control is enforced systemically rather than by convention. Good evidence identifies the accountable owner and shows thresholds are written and current; approver independence is demonstrable from system records; split-transaction analysis covers the complete population.","exampleArtifacts":["Approved delegation of authority matrix","System configuration enforcing thresholds","Sample of approvals showing independence","Monthly split-transaction and override report"],"likelyEvidenceOwner":"Finance and operational process owners","controlObjective":"Require genuinely independent review or approval for transactions and activities above defined risk or value thresholds.","contentFingerprint":"7ea53450169cf1eb15a70f59958b930c7226d55986f7b8a279639da9ac162092","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Every supplier is verified against legal identity, ownership, tax/banking and risk indicators before activation, with enhanced review for high-risk suppliers. Good evidence identifies the accountable owner and shows covers the full supplier population added in the period; evidence predates activation; reviewer is different from requester.","exampleArtifacts":["Completed onboarding checklist","Independent registration and bank verification","Beneficial-ownership/conflict screening","Second-reviewer approval"],"likelyEvidenceOwner":"Procurement / Vendor Master","controlObjective":"Prevent fictitious, conflicted or misrepresented suppliers from entering the approved vendor population.","contentFingerprint":"1b0dd1f1374eae039d3f675f1123249964009f520a98111d19914f004ca26c7e","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"All in-scope user access maps to an approved role, is reviewed by the business owner each quarter and is removed promptly after role change or exit. Good evidence identifies the accountable owner and shows reconciles to the complete active-user population; shows reviewer, decision and date per entitlement; includes closure evidence for removals.","exampleArtifacts":["Complete user-entitlement export","Approved role-to-access matrix","Manager recertification decisions","Exception and removal tickets"],"likelyEvidenceOwner":"Business system owners","controlObjective":"Keep ordinary system and data access aligned to current job responsibilities.","contentFingerprint":"05a559d2262f521b8674c9c93c365f5115c1cf9b88f97ec76e450573fea6d70a","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Refunds, credits, write-offs, stock adjustments, manual journals and overrides are captured completely, require documented reason codes, and are reviewed independently against the full population. Good evidence identifies the accountable owner and shows population reconciles to system control totals; reviewer is outside the originating team; shows both threshold-based and sample-based coverage.","exampleArtifacts":["Complete manual adjustment population extract","Reason codes and supporting justification","Independent review records","Escalation log for pattern exceptions"],"likelyEvidenceOwner":"Finance Control and operations owners","controlObjective":"Bring sensitive manual adjustments under independent review because they bypass normal transactional controls.","contentFingerprint":"74cd2f7ca2602e8d0531cdf031b80d2a548b16d78dd2172117f7b3093ee6e9d5","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Material processes are reviewed on a defined cycle against how they actually operate, with weaknesses logged, owned and tracked to closure. Good evidence identifies the accountable owner and shows reviews the process as performed, not only as documented; includes transaction-level testing; weaknesses tracked to evidenced closure.","exampleArtifacts":["Process review schedule and coverage plan","Completed review reports with walkthrough evidence","Weakness log with owners and due dates","Closure evidence"],"likelyEvidenceOwner":"Head of Risk with process owners","controlObjective":"Periodically re-examine operational processes for control weaknesses and manipulation opportunities that have emerged in practice.","contentFingerprint":"65ea5411b861283da2afa29e2256ddb5820d19cd5f658b9203d129e3f9a914af","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D3-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"High-risk roles are identified explicitly and subject to defined compensating measures such as secondary review, rotation, mandatory leave or enhanced monitoring, applied consistently and fairly. Good evidence identifies the accountable owner and shows role list derived from authority, access and custody; shows the measure actually operated, not only assigned; applied consistently across comparable roles.","exampleArtifacts":["Defined high-risk role list with rationale","Applied oversight measures per role","Cover or rotation records","Annual coverage and fairness review"],"likelyEvidenceOwner":"Human Resources with process owners","controlObjective":"Apply proportionate oversight to roles whose authority, access or custody creates elevated fraud opportunity.","contentFingerprint":"82cc2ba389cf2689e7fde8d22600cc118ee97683987b260cf11927094ef24673","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Defined monitoring covers the material transaction and activity population, uses risk-based indicators, and produces reviewable output on a set rhythm rather than relying on incidental discovery. Good evidence identifies the accountable owner and shows runs against the complete population, not a convenience sample; indicators map to identified fraud scenarios; output is routed to a named reviewer.","exampleArtifacts":["Red-flag indicator definitions per process","Monitoring output for recent periods","Population reconciliation to source systems","Coverage report against process fraud maps"],"likelyEvidenceOwner":"Fraud monitoring owner","controlObjective":"Actively monitor transactions and operational activity for unusual patterns, anomalies and red flags.","contentFingerprint":"08082f90430b52fe960aeaa533d5d5bef59be89360f645e16ccf56b1a80af6a0","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"The complete alert population is assigned, triaged to risk-based SLAs, dispositioned with evidence and independently reviewed for ageing and quality. Good evidence identifies the accountable owner and shows shows completeness reconciliation; records reviewer, timestamps and rationale; separates closure-quality reviewer from alert investigator.","exampleArtifacts":["Exception population and control totals","Alert investigation log","Disposition evidence","Monthly quality-review sample"],"likelyEvidenceOwner":"Fraud monitoring owner","controlObjective":"Ensure generated fraud and control exceptions are actually investigated and resolved.","contentFingerprint":"dec638f0746d94ef107dbae7f10cb0fef37316879f45d615ed48818048d4caf3","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A maintained catalogue of rules and data checks maps each test to a fraud scenario, runs against reconciled data, and is tuned from confirmed outcomes. Good evidence identifies the accountable owner and shows each rule states scenario, source, threshold and reviewer; results reconcile to source system totals; tuning decisions are evidence-based.","exampleArtifacts":["Rule and data-check catalogue with scenario linkage","Execution logs and results","Source reconciliation evidence","Monthly tuning record with true/false positive outcomes"],"likelyEvidenceOwner":"Fraud analytics owner","controlObjective":"Use analytics, rules, reports or data checks to surface suspicious transactions, behaviour and control exceptions.","contentFingerprint":"cf8ef33b4a724aeab220e731c26df3ae554c430a0f1ac60051fe40017d13e702","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Defined triggers require detection rules and indicators to be reassessed, with changes recorded, tested before deployment and reported to the fraud forum. Good evidence identifies the accountable owner and shows changes traceable to a dated trigger; tested before deployment; version history retained.","exampleArtifacts":["Change triggers and rule version history","Rationale for each detection change","Pre-deployment test results against historical data","Coverage reporting to the fraud forum"],"likelyEvidenceOwner":"Fraud monitoring owner","controlObjective":"Keep detection controls current as fraud methods, risks and operations change.","contentFingerprint":"98fd59d3144da6117fc0e8ceea490a82fc6b7d88e0ca2a6f683d332b88b3546a","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Monitoring explicitly addresses employee and insider misuse alongside external attack, with indicators, data sources and reviewers defined for both. Good evidence identifies the accountable owner and shows separates internal and external indicators explicitly; covers every material process; gaps carry named owners and due dates.","exampleArtifacts":["Internal versus external coverage matrix","Indicator definitions for both threat classes","Gap log with owners","Coverage report to the fraud forum"],"likelyEvidenceOwner":"Fraud monitoring owner","controlObjective":"Cover both internal misuse and external fraud threats within the monitoring design.","contentFingerprint":"b7f053afc207ff671aab65b7ba0b6af0abddc8cffc9108920469789d09d3bc72","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Written escalation criteria, routes and timeframes are defined, staff are trained on them, and escalation can bypass any implicated line manager. Good evidence identifies the accountable owner and shows states criteria, recipient and timeframe explicitly; provides a conflict-free alternate route; timeliness measured against the stated criteria.","exampleArtifacts":["Written escalation criteria and routes","Evidence of alternate route bypassing implicated management","Training completion records","Quarterly escalation timeliness review"],"likelyEvidenceOwner":"Fraud monitoring team lead","controlObjective":"Ensure monitoring staff know when to escalate and hold the authority to do so without obstruction.","contentFingerprint":"ebfbbbdaeb209b5de251032c5f675cebf8bcc4e92dbd282db08be60cb36aab87","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D4-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A reviewer independent of the monitoring team periodically evaluates detection coverage, output quality and closure integrity, and reports findings to governance. Good evidence identifies the accountable owner and shows reviewer is independent of the monitoring team; includes retesting of closed alerts, not only design review; findings tracked to evidenced closure.","exampleArtifacts":["Independent review scope and report","Coverage assessment against process fraud maps","Closed-alert retesting results","Remediation tracking to closure"],"likelyEvidenceOwner":"Internal Audit or independent reviewer","controlObjective":"Independently test whether detection controls are actually working, not merely running.","contentFingerprint":"40df10d034b153c8507afd7587519ea0d84e22724071a63aa835bff001dfb5dd","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A documented plan defines intake, severity, command roles, containment, legal/evidence decisions, communications and closure, and is rehearsed annually. Good evidence identifies the accountable owner and shows names commander, deputies and severity triggers; timestamps decisions and assigned actions; shows tabletop findings closed.","exampleArtifacts":["Approved incident-response plan","Incident decision and action log","Annual tabletop record","Lessons-learned tracker"],"likelyEvidenceOwner":"Fraud incident-response lead","controlObjective":"Create a repeatable, coordinated response to suspected fraud.","contentFingerprint":"5adb50c016670f4871155e4c8124d62bc24ba27b8eca01e6385a58b5ebb1d416","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Reporting routes are published in plain language, reach the entire workforce including non-desk and contract staff, and awareness is periodically tested rather than assumed. Good evidence identifies the accountable owner and shows reaches the full workforce, not only email users; states more than one route including a conflict-free option; awareness measured rather than assumed.","exampleArtifacts":["Published reporting route material","Distribution evidence covering non-desk and contract staff","Awareness test or survey results","Targeted re-communication records where results were low"],"likelyEvidenceOwner":"Ethics / Compliance lead","controlObjective":"Make sure every employee knows exactly where and how to report suspected fraud or misconduct.","contentFingerprint":"9f31cf12ec0909ad929cc9a151928d28dbd6a0478747c8a6f46b8d247f288d89","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A written matrix assigns decision rights for triage severity, investigation authorisation, disciplinary and legal referral, recovery and closure, with conflict rules and deputies named. Good evidence identifies the accountable owner and shows covers triage through closure, not investigation alone; names deputies for every decision; case records show who decided and why.","exampleArtifacts":["Approved decision-rights matrix","Named primaries and deputies","Documented conflict and recusal rules","Case files showing decisions with date and rationale"],"likelyEvidenceOwner":"Fraud incident-response lead","controlObjective":"Define who decides what at each stage of fraud triage, investigation, escalation and closure.","contentFingerprint":"5b86ace87b9841c69399a38ea0a8a90cfe8aa5f75d1f54e553c1dc64dc2fb4dd","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Written investigation procedures govern confidentiality, subject fairness, interview conduct, documentation standards and legal privilege considerations, and investigators are competent to apply them. Good evidence identifies the accountable owner and shows addresses confidentiality and subject fairness explicitly; documentation is contemporaneous and dated; closure review performed against the written procedure.","exampleArtifacts":["Written investigation procedure","Case access restriction records","Contemporaneous interview and file notes","Closure quality-review checklist"],"likelyEvidenceOwner":"Investigation lead","controlObjective":"Conduct investigations so that confidentiality, fairness and documentary integrity are protected throughout.","contentFingerprint":"efce4535b91d0e07fc66a3cfca1cccf046e222d2d1dd49c95dd8d3450fcb1bca","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Evidence is collected under legal direction where needed, hashed or sealed, logged through every transfer, access-restricted and retained under an approved schedule. Good evidence identifies the accountable owner and shows unique evidence identifier on every item; unbroken timestamped custody trail; hash or seal reconciles at handover.","exampleArtifacts":["Evidence register","Chain-of-custody forms","Hash or seal records","Repository access log"],"likelyEvidenceOwner":"Investigation lead / Evidence custodian","controlObjective":"Identify, preserve and account for fraud evidence so integrity and provenance can be demonstrated.","contentFingerprint":"13e14a220ed16fcf0a4eaf4e9f2af03453cf63a063d8081e6c662a1f3e46589d","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Criteria define when external specialists are engaged, pre-qualified providers are identified in advance, and engagement terms protect confidentiality, privilege and evidential integrity. Good evidence identifies the accountable owner and shows triggers are objective and assessed at triage; providers pre-qualified before an incident, not during one; terms address privilege, confidentiality and evidence handling.","exampleArtifacts":["Written engagement trigger criteria","Pre-qualified provider list with agreed terms","Engagement or non-engagement decision per qualifying case","Confidentiality and evidential-standard clauses"],"likelyEvidenceOwner":"Fraud incident-response lead","controlObjective":"Bring in specialist forensic, legal, cyber or investigative capability when a case exceeds internal capability.","contentFingerprint":"30f9a7cd63b5c12e55077aaa95bb05afe23eaf3b6084794bd759212b5f5750ad","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D5-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Every material incident produces a documented root-cause review with control actions, owners and due dates, tracked to evidenced closure and verified for effect. Good evidence identifies the accountable owner and shows identifies control failure, not only individual culpability; actions carry named owners and due dates; verification confirms the control now operates.","exampleArtifacts":["Post-incident review reports","Root-cause analysis identifying failed or absent controls","Remediation register entries with owners and due dates","Post-implementation verification evidence"],"likelyEvidenceOwner":"Fraud incident-response lead","controlObjective":"Convert what each incident reveals into control improvements that reduce repeat exposure.","contentFingerprint":"867792c1cba840fd5db7aba69394c9863bb62969c76c01f0dae7adac94b32848","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A confidential and, where lawful, anonymous channel is continuously available, independently administered, access-restricted and protected by anti-retaliation escalation. Good evidence identifies the accountable owner and shows supports confidential and anonymous intake; shows restricted identities and conflict routing; tracks acknowledgement and ageing.","exampleArtifacts":["Channel configuration and availability test","Role-based case access list","Anonymised case register","Anti-retaliation escalation records"],"likelyEvidenceOwner":"Ethics / Compliance lead","controlObjective":"Provide a safe, confidential route for internal and relevant external fraud concerns.","contentFingerprint":"90a6be3888bcf67f8b494cc129aea2118110f0e63332c6eb2a7e0fc3f008de12","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Channel instructions are published in the languages and formats the workforce uses, explain what happens after a report, and awareness and usability are periodically tested. Good evidence identifies the accountable owner and shows explains anonymity and expected feedback; available in the languages and formats staff actually use; live test confirms intake through to case creation.","exampleArtifacts":["Published channel instructions in relevant languages and formats","Annual live channel test record","Awareness measurement results","Follow-up communication where awareness was low"],"likelyEvidenceOwner":"Ethics / Compliance lead","controlObjective":"Ensure the workforce actually knows how to use the confidential reporting channel, not merely that one exists.","contentFingerprint":"c8850599a0c852c4a05fa7785f4d73dd4f443979e08abcbabae25b759b0731fb","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Triage routing rules automatically divert cases away from implicated individuals and their reporting lines, with an independent escalation route for reports naming senior management. Good evidence identifies the accountable owner and shows excludes implicated parties and their reporting line; provides a route independent of executive management; access to case data is restricted and logged.","exampleArtifacts":["Documented routing and conflict rules","Per-case routing decisions","Role-based case access list and access logs","Evidence of the alternate route for executive-level reports"],"likelyEvidenceOwner":"Ethics / Compliance lead","controlObjective":"Guarantee that reports are assessed independently of the people or teams they implicate.","contentFingerprint":"cd3a13d1fae0df4918088873f7bb21473e1d3b6749639a55bdccac1acd047638","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A communicated anti-retaliation position is backed by monitoring of reporters’ employment outcomes, a route to raise retaliation concerns, and enforced consequences. Good evidence identifies the accountable owner and shows covers contractors as well as employees; outcome monitoring is active rather than complaint-driven; substantiated retaliation results in recorded consequences.","exampleArtifacts":["Written anti-retaliation commitment","Communication records","Reporter outcome monitoring records","Retaliation allegations and their resolution"],"likelyEvidenceOwner":"Human Resources with Ethics lead","controlObjective":"State and enforce that retaliation against people who raise concerns is prohibited.","contentFingerprint":"9dbab2a0ecaf3c151c6b070e30ae8a5f2e2270a782dbb9ff49fd477e3ba120fa","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Where suppliers, contractors, customers or beneficiaries are relevant, the channel is externally reachable, publicised to them, and handles external reports under the same independence rules. Good evidence identifies the accountable owner and shows reachable without internal network access or credentials; communicated to the relevant external population; external reports triaged under the same conflict rules.","exampleArtifacts":["Publicly reachable channel route","Supplier contract or onboarding references to the channel","External report register","Triage records applying the same independence rules"],"likelyEvidenceOwner":"Ethics / Compliance lead","controlObjective":"Extend reporting access to external stakeholders who observe misconduct the workforce cannot see.","contentFingerprint":"4b9edf03b255f80eccd046efb092814431053904aa12435388b2bab03da81180","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D6-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Guidance and training describe observable indicators relevant to the organisation’s roles and settings, set the threshold for reporting suspicion rather than proof, and are refreshed with real anonymised cases. Good evidence identifies the accountable owner and shows indicators are observable and role-relevant, not abstract; states clearly that proof is not required to report; refreshed using real anonymised cases.","exampleArtifacts":["Guidance and training content showing observable indicators","Completion records across the workforce","Statement of the suspicion-not-proof threshold","Content refresh records after incidents"],"likelyEvidenceOwner":"Learning and Development with Ethics lead","controlObjective":"Equip employees to recognise the behavioural and situational signals that should prompt a report.","contentFingerprint":"df7060bfbaba254304827248cb1e81ef24ee21285febecb568ae009143d78199","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"All third parties receive proportionate identity, ownership, sanctions/conflict and capability checks before contracting, with enhanced approval for high-risk relationships. Good evidence identifies the accountable owner and shows evidence predates engagement; uses independent source data; documents match resolution and approver.","exampleArtifacts":["Third-party risk rating","Identity and beneficial-ownership verification","Sanctions/adverse/conflict screening","High-risk approval"],"likelyEvidenceOwner":"Procurement / Vendor Risk","controlObjective":"Risk-screen every supplier, contractor or third party before engagement.","contentFingerprint":"2b5e8db07e64eb042303d6c9708c69b06973ba9338caff4b104239b05449ae9f","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Sourcing above defined thresholds follows a documented competitive process with sealed submissions, evaluation by a panel against pre-set criteria, conflict declarations and independent review of single-source awards. Good evidence identifies the accountable owner and shows criteria demonstrably pre-date bid opening; panel evaluation with declared conflicts, not a single evaluator; pattern analysis covers the complete award population.","exampleArtifacts":["Pre-set evaluation criteria dated before submission opening","Sealed-bid opening records with witnesses","Panel conflict declarations and scoring sheets","Single-source justifications and approvals"],"likelyEvidenceOwner":"Procurement lead","controlObjective":"Protect competitive sourcing from collusion, manipulation, bid rigging and favouritism.","contentFingerprint":"b689e0131a1b5f13603a85fd5edf79973cfcd3d7ce730859c0d03c24a224d912","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Declarations are collected from all staff able to influence supplier selection or payment, refreshed periodically and on change, tested against supplier data, and each declared conflict carries a documented management action. Good evidence identifies the accountable owner and shows covers all roles able to influence selection or payment; includes proactive data matching, not declaration alone; each conflict has an applied and evidenced management action.","exampleArtifacts":["Declaration register covering all in-scope roles","Data-matching results against the vendor master","Conflict register with management actions","Evidence of recusal or enhanced review being applied"],"likelyEvidenceOwner":"Compliance with Human Resources","controlObjective":"Surface and actively manage employee conflicts of interest involving suppliers and third parties.","contentFingerprint":"05f4d516f9664b34e117df2c80bd69ac6ae94c04c416f1a05a13d259ce145f7d","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Every bank-detail change is verified independently through a trusted pre-existing contact and segregated from payment approval; invoices are matched to approved supplier and purchasing records. Good evidence identifies the accountable owner and shows callback number predates the request; requester, verifier and approver are separated; covers the complete bank-change population.","exampleArtifacts":["Bank-detail-change request","Pre-existing contact record and callback log","Independent approval","Payment hold/release audit trail"],"likelyEvidenceOwner":"Accounts Payable / Vendor Master","controlObjective":"Prevent invoice manipulation and fraudulent vendor bank-detail changes before payment release.","contentFingerprint":"505ffdbf2e3fffa6c2ae15b8113b37168f1074cfa75a3cf6c0a9df8c575c1330","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"High-risk third parties are re-screened and performance-reviewed on a risk-based cycle covering ownership change, sanctions status, delivery performance, pricing drift and spend concentration. Good evidence identifies the accountable owner and shows covers the complete high-risk population; includes re-screening, not performance review alone; findings tracked to evidenced action.","exampleArtifacts":["Risk-tiered monitoring schedule","Re-screening results for ownership and sanctions","Performance and pricing review records","Spend concentration analysis"],"likelyEvidenceOwner":"Procurement / Vendor Risk","controlObjective":"Keep high-risk third-party relationships under periodic review after onboarding, not only at the point of engagement.","contentFingerprint":"5c5376169cdbf931496e797feecf95fc2f79aec29983ab542c4d575356dc7c19","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"An independent function periodically reviews procurement and vendor-master activity covering master-data changes, award patterns, spend outside contract and policy exceptions. Good evidence identifies the accountable owner and shows reviewer independent of procurement and finance operations; covers vendor-master changes and award patterns by individual; findings tracked to evidenced closure.","exampleArtifacts":["Independent review scope and report","Vendor-master change log with approvers","Award and exception pattern analysis by individual","Findings tracked to closure"],"likelyEvidenceOwner":"Internal Audit or independent reviewer","controlObjective":"Subject procurement and vendor-management activity itself to oversight, since it controls both supplier selection and payment eligibility.","contentFingerprint":"2f045f42745fc7a08f1440d041a609f94390f672433b2ec67f2beb50f983bcba","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D7-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Intermediary and outsourced arrangements carry contractual fraud-control obligations, audit and information rights, defined oversight of delegated authority, and periodic assurance over the provider’s own controls. Good evidence identifies the accountable owner and shows contract states audit rights and authority limits explicitly; reconciliation covers the complete delegated transaction population; sub-contracting requires prior approval.","exampleArtifacts":["Contract clauses covering fraud controls, audit rights and delegated authority limits","Reconciliation of intermediary-handled transactions or collections","Assurance over provider controls","Sub-contracting approvals"],"likelyEvidenceOwner":"Relationship owner with Procurement","controlObjective":"Address the specific fraud risks created by agents, brokers, distributors, intermediaries and outsourced providers acting on the organisation’s behalf.","contentFingerprint":"1c85ac82dd5b2946bd5137a8ec00b1aa1554538f3a64aed27140a6d26b36f753","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Identity verification is applied at defined risk points using independent sources proportionate to risk, with results recorded, exceptions approved and re-verification on sensitive change. Good evidence identifies the accountable owner and shows uses independent sources rather than self-supplied documents alone; verification predates activation or first payment; retention respects applicable data-protection obligations.","exampleArtifacts":["Defined verification risk points and required checks","Verification records with source and date","Exception approvals","re-verification records for sensitive changes"],"likelyEvidenceOwner":"Process owners for onboarding and activation","controlObjective":"Verify the identity of customers, users, employees, suppliers and counterparties wherever identity misuse could create loss or harm.","contentFingerprint":"b62211f0c666e4b70a693c9b866a21ea4977be90cf2170fddf8eecd4c9c1c2ab","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Risk-based monitoring covers material digital events, alerts are triaged to defined SLAs and rules are tuned from confirmed outcomes. Good evidence identifies the accountable owner and shows reconciles monitored events to source feeds; maps each rule to a risk and sla; records evidence-based disposition.","exampleArtifacts":["In-scope event inventory","Monitoring-rule catalogue","Alert case records","Monthly tuning and coverage report"],"likelyEvidenceOwner":"Security monitoring / SOC","controlObjective":"Detect suspicious login, account, access and transaction behaviour on digital platforms.","contentFingerprint":"8e720708535c656163346f479b7bd37529fa9d22333138f5b5e8b827d2c0ea2f","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Training is role-relevant, reinforced by periodic simulations, measured by behaviour rather than completion alone, and supported by a fast reporting route with feedback. Good evidence identifies the accountable owner and shows targets high-risk roles specifically; measures report rate, not completion alone; links to an out-of-band verification requirement.","exampleArtifacts":["Role-relevant training content and completion records","Simulation results including click and report rates","Reporting route usage statistics","Verification procedure for payment and bank-detail instructions"],"likelyEvidenceOwner":"Security awareness owner","controlObjective":"Prepare employees to recognise and resist phishing, social engineering and digital impersonation.","contentFingerprint":"977b38d345e5649f3d812dddc42d5f6d16ac4b4dfc37706017426e995de7bbcb","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Every privileged account is named, justified, least-privileged, strongly authenticated, logged and independently recertified quarterly; emergency access expires automatically. Good evidence identifies the accountable owner and shows covers human, service, shared and emergency accounts; separates reviewer from account administrator; shows owner, decision, date and closure.","exampleArtifacts":["Privileged-account register","Approval and business justification","Quarterly independent recertification","Privileged-session/access logs"],"likelyEvidenceOwner":"Identity and Access Management","controlObjective":"Restrict and independently recertify privileged, administrator and sensitive-data access.","contentFingerprint":"70d9a0e890894921c2be0d8a238cfc7f3817abef632cd4b488770bc57eb70312","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Monitoring joins user, transaction and change events across material digital channels, with risk-based triage and retained investigation evidence. Good evidence identifies the accountable owner and shows maps scenarios to events and thresholds; proves source-feed completeness; records analyst rationale and escalation.","exampleArtifacts":["Misuse-case catalogue","Event-feed reconciliation","Alert investigations","Monthly effectiveness report"],"likelyEvidenceOwner":"Digital fraud operations","controlObjective":"Detect misuse, unauthorised transactions, suspicious data changes and digital-channel abuse.","contentFingerprint":"0ccebeec0c773a79818789df9f31aa518a16ab0aefb46da7c572ef0c2efc935a","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Reporting routes are published for both staff and external users, monitored during defined hours with defined response times, and feed directly into monitoring and incident response. Good evidence identifies the accountable owner and shows covers both internal staff and external users where relevant; states monitored hours and response targets; demonstrates connection to incident response.","exampleArtifacts":["Published reporting routes for staff and users","Defined response-time targets","Report register with response times","Evidence reports feed into triage and incident response"],"likelyEvidenceOwner":"Security operations","controlObjective":"Give employees and users a fast, known route to report suspicious digital activity or account-security concerns.","contentFingerprint":"c24bdae26d7db7ac2c5c1d50c635f1ad6a811aacd1f6bef5cbcd80ce89442cfe","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q07","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Digital threat review runs on a defined cycle covering channel-specific attack methods, assesses them against current controls, and produces owned actions or explicit accept decisions. Good evidence identifies the accountable owner and shows specific to the organisation’s channels and technology; assesses each method against named controls; every gap has an owner or an explicit accept decision.","exampleArtifacts":["Digital threat review records with sources","Assessment against current controls","Action log with owners and due dates","Recorded accept decisions with rationale"],"likelyEvidenceOwner":"Information Security with digital channel owners","controlObjective":"Periodically reassess emerging digital fraud risks relevant to the organisation’s operations and sector.","contentFingerprint":"c32b0550874a4c03b5ffe4b1e6c0c7f127bcb1d46fffde606a370589f533e7c3","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D8-Q08","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Sufficient logging, alerting and investigative capability exists to identify compromise, reconstruct what occurred, contain it and support recovery or referral. Good evidence identifies the accountable owner and shows covers authentication, profile change and transaction events together; retention supports investigation within the defined window; runbook includes containment actions.","exampleArtifacts":["Log coverage inventory for identity-bearing systems","Defined retention period and data-protection basis","Alert definitions for takeover indicators","Investigation runbook and a worked case example"],"likelyEvidenceOwner":"Security operations with identity owners","controlObjective":"Be able to detect and investigate identity misuse, account takeover, impersonation and unauthorised profile changes.","contentFingerprint":"94e29b802299223b36049916f95e5c62a06c095f69b6fc3099671d5824969e86","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Role-based fraud learning is completed at induction and annually, refreshed for emerging risks and tested for understanding and behaviour. Good evidence identifies the accountable owner and shows reconciles to the active employee population; uses role-specific scenarios; records pass threshold, retries and escalation.","exampleArtifacts":["Role-to-training matrix","Current scenario-based content","Employee completion and assessment results","Overdue escalation log"],"likelyEvidenceOwner":"Learning and Development","controlObjective":"Equip staff to recognise and act on fraud risks specific to their roles.","contentFingerprint":"d3187181a022a31d57155875b46ea90f3ba42e7ecc43458c62c7f554add6e3ab","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Induction includes fraud content covering policy, reporting routes, consequences and role-relevant risks, is completed within a defined period of joining, and covers contractors where they hold equivalent access. Good evidence identifies the accountable owner and shows reconciles to the complete joiner population from hr records; covers contractors with equivalent access; records completion date against start date.","exampleArtifacts":["Induction fraud module content","Completion records reconciled to the joiner population","Contractor coverage evidence","Overdue escalation log"],"likelyEvidenceOwner":"Human Resources / Learning and Development","controlObjective":"Establish fraud expectations at the point of joining, before habits and local practice form.","contentFingerprint":"cf617b20df6ef546b334d0c80dd7b7db0b555b8f41c8647c4a9bad24d319a155","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Leaders communicate expectations on a defined rhythm through visible channels, model them in decisions, and reinforce that results never justify control bypass. Good evidence identifies the accountable owner and shows reaches non-desk and field workforce; states explicitly that targets do not justify bypass; paired with visible follow-through.","exampleArtifacts":["Leadership communication records with dates and reach","Content showing conduct and control-bypass expectations","Team forum reinforcement evidence","Anonymised case outcome communications"],"likelyEvidenceOwner":"Executive team with Internal Communications","controlObjective":"Have leadership set explicit, repeated expectations on ethical conduct, conflicts and fraud prevention.","contentFingerprint":"0bda953d32f5417c29beaa419800e6f15e32159d695219a060e4a705ca0c07b7","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Consequences are documented in policy and employment terms, applied consistently regardless of seniority, and communicated through anonymised outcomes so deterrence is credible. Good evidence identifies the accountable owner and shows consequences documented and contractually referenced; outcome consistency reviewed across seniority levels; communication preserves anonymity.","exampleArtifacts":["Disciplinary framework stating fraud consequences","Employment terms referencing them","Case outcome records by seniority","Annual consistency review"],"likelyEvidenceOwner":"Human Resources","controlObjective":"Ensure employees understand the actual consequences of fraudulent, dishonest or unethical behaviour.","contentFingerprint":"08b107c22597f259f50df17325c4fd08d6ae95ac8595e4f3037937b60ed7b0f9","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Awareness material uses anonymised real cases and realistic scenarios drawn from the organisation’s own processes and sector, refreshed as methods change. Good evidence identifies the accountable owner and shows scenarios reflect the organisation’s own processes; anonymisation prevents identification of individuals; responses captured to identify weak areas.","exampleArtifacts":["Anonymised case and scenario library","Scenario-based assessment results","Mapping of scenarios to organisational processes","Refresh records after incidents"],"likelyEvidenceOwner":"Learning and Development with Fraud Risk","controlObjective":"Use real examples, scenarios and lessons learned so staff recognise fraud as it actually presents.","contentFingerprint":"c3d7c4d01f99e2f9ef470c710731aa2470008f062f7797df212877b58430b61e","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D9-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Perceived safety is actively measured, feedback is given to reporters, outcomes are visible in anonymised form, and identified trust gaps are acted on. Good evidence identifies the accountable owner and shows results segmented by site and level, not organisation-wide only; feedback timeliness measured per case; below-threshold segments carry owned actions.","exampleArtifacts":["Survey instrument and segmented results","Reporter feedback timeliness records","Anonymised outcome publications","Action plans for below-threshold segments"],"likelyEvidenceOwner":"Human Resources with Ethics lead","controlObjective":"Build genuine confidence that raising a concern is safe and will be taken seriously.","contentFingerprint":"b2e3bc7b197aac478863995461073500ffa51c3c48062d0cd4073879939d0086","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q01","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A scheduled review reassesses fraud risks, tests whether key controls still operate as designed, and reports a consolidated position with owned actions to governance. Good evidence identifies the accountable owner and shows tests operation with sampled evidence, not attestation alone; covers the full key-control set; actions carry named owners and due dates.","exampleArtifacts":["Review scope and schedule","Key control operating evidence sampled in the period","Lapsed or degraded control register","Consolidated report to governance with actions and due dates"],"likelyEvidenceOwner":"Head of Risk","controlObjective":"Periodically re-examine the fraud risk profile and the control environment as a whole rather than only at incident time.","contentFingerprint":"1e32ab6e927a2f3dcd9622716f1ab8a57fdad3ef7c07a1b92e8e6850abce2ffd","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q02","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"A structured root-cause method is applied to material incidents and near-misses, distinguishing design failure, operating failure and absent control, with themes aggregated across cases. Good evidence identifies the accountable owner and shows classifies cause type rather than describing events; includes near-misses, not only realised losses; aggregates themes across multiple cases.","exampleArtifacts":["Structured root-cause method","Completed analyses with cause classification","Near-miss records","Thematic aggregation reports"],"likelyEvidenceOwner":"Head of Risk with incident lead","controlObjective":"Analyse incidents and control failures to understand why they were possible, not merely what happened.","contentFingerprint":"64a19f6fffb451c9aba1c9f43a5f7358985e314350234004537159c6f2f4dbd2","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q03","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Each lesson becomes a specific change with an owner, due date and implementation evidence, verified afterwards to confirm the weakness is closed. Good evidence identifies the accountable owner and shows each lesson maps to a specific named change; closure requires evidence, not assertion; verification confirms operation after implementation.","exampleArtifacts":["Remediation register linking lessons to specific changes","Owners, due dates and completion evidence","Overdue review records","Post-implementation verification"],"likelyEvidenceOwner":"Head of Risk with control owners","controlObjective":"Translate lessons from investigations and incidents into actual changes in controls, process, training or monitoring.","contentFingerprint":"944d7d3b1a13abef5b3f26504b84636a71724e41365a9e230e96105ca3cb9b6b","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q04","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"External trend monitoring is assigned, run on a defined rhythm, compared against internal loss and incident patterns, and reported with implications for control priorities. Good evidence identifies the accountable owner and shows covers sector, geography, customer and supplier dimensions; compares external trends with internal data; states implications rather than summarising news.","exampleArtifacts":["Assigned monitoring responsibility and source set","Trend reports with dated sources","Comparison against internal incident and loss data","Implications recorded for control priorities"],"likelyEvidenceOwner":"Fraud risk analyst or nominated owner","controlObjective":"Monitor fraud trends affecting the organisation’s sector, geography, customer environment and supplier base.","contentFingerprint":"9a7d08b665969c1000d1b5bd1d12d1dfb37fd9d7773a267e1a8577fac0173a4d","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q05","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Fraud consideration is embedded as a required, evidenced step in the change lifecycle with sign-off before implementation and post-implementation confirmation that intended controls operate. Good evidence identifies the accountable owner and shows sign-off predates implementation; names the owner of each control in the live state; post-implementation check confirms operation.","exampleArtifacts":["Change records showing fraud consideration and sign-off","Named control owners for the live state","Deferred control log with due dates","Post-implementation control operation checks"],"likelyEvidenceOwner":"Change and project governance owner","controlObjective":"Ensure fraud risk is considered whenever new systems, products, services, processes or operational changes are implemented.","contentFingerprint":"b05e9482ac14dc1155cf15fd7c2bd1b73720399f0136095cd591600bab1ee0fd","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"},{"questionCode":"D10-Q06","guidanceVersion":"MFRS-V1.1-G28-20260804","goodEvidenceLooksLike":"Leadership reviews a consolidated view of key control operation, resourcing and capability on a defined rhythm and records explicit decisions on gaps. Good evidence identifies the accountable owner and shows addresses resourcing and capability, not only operation; every gap carries an explicit recorded decision; decisions tracked to implementation.","exampleArtifacts":["Consolidated key control effectiveness and resourcing view","Evidence of operation per control","Capacity, skills and tooling assessment","Recorded leadership decisions and tracking"],"likelyEvidenceOwner":"Named fraud-risk executive","controlObjective":"Have leadership periodically confirm that key fraud controls remain effective, adequately resourced and fit for purpose.","contentFingerprint":"0af828b60fcbdfa4dd33fee940ef85b53ce645c9d3ba9243267fb9b715832c9a","graphVersion":"MFRS-V1.1-ADAPTIVE-DRAFT-20260804","methodologyVersion":"MFRS-V1.1"}]'::jsonb) as g(questionCode text, guidanceVersion text, goodEvidenceLooksLike text, exampleArtifacts jsonb, likelyEvidenceOwner text, controlObjective text, contentFingerprint text, graphVersion text, methodologyVersion text)
join public.methodology_versions mv on mv.version_code = g.methodologyVersion
join public.adaptive_graph_versions ag on ag.graph_version = g.graphVersion
join public.questions q on q.question_code = g.questionCode and q.methodology_version_id = mv.id
on conflict (question_id, methodology_version_id, guidance_version) do nothing;

commit;
